-- =====================================================================\n-- V12: crear app_user (NOSUPERUSER NOBYPASSRLS) para que RLS aplique\n--      en runtime y en Testcontainers (que no monta el init script).\n-- =====================================================================\n\nDO $$\nBEGIN\n  IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'app_user') THEN\n    CREATE ROLE app_user WITH NOLOGIN\n      NOSUPERUSER NOBYPASSRLS NOCREATEDB NOCREATEROLE;\n  END IF;\nEND $$;\n\n-- Permisos sobre BD y schema (idempotente)\nDO $$\nBEGIN\n  EXECUTE 'GRANT CONNECT ON DATABASE ' || current_database() || ' TO app_user';\nEXCEPTION WHEN OTHERS THEN\n  -- si el usuario no tiene permisos, no fallar; se configura en deploy\n  NULL;\nEND $$;\n\nGRANT USAGE ON SCHEMA public TO app_user;\n\n-- Grants sobre tablas/funciones existentes\nGRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO app_user;\nGRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO app_user;\nGRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA public TO app_user;\n\n-- Default privileges para tablas futuras creadas por el usuario de migración\nALTER DEFAULT PRIVILEGES IN SCHEMA public\n  GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO app_user;\nALTER DEFAULT PRIVILEGES IN SCHEMA public\n  GRANT USAGE, SELECT ON SEQUENCES TO app_user;\nALTER DEFAULT PRIVILEGES IN SCHEMA public\n  GRANT EXECUTE ON FUNCTIONS TO app_user;